package com.intermarche.backoffice.engine.fieldops;
import static com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id;
import com.intermarche.backoffice.domain.inventory.*;
import com.intermarche.backoffice.domain.stock.*;
import com.intermarche.backoffice.domain.store.*;
import com.intermarche.backoffice.domain.wms.handling.InventoryOrder;
import com.intermarche.backoffice.domain.wms.BaseHandlingOrder;
import com.intermarche.backoffice.domain.util.DateTimeProvider;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;
import jakarta.ws.rs.*;
import java.util.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;
/** A targeted mission snapshots its perimeter at creation; it never freezes unrelated stock. */
@ApplicationScoped @Transactional
public class InventoryService {
 @Inject FieldOperationsService field; @Inject StockCommands receipts;
 @Inject com.intermarche.backoffice.engine.storeops.PlanningAssignmentService assignments;
 @org.eclipse.microprofile.openapi.annotations.media.Schema(name="InventoryMissionInput") public static class Input {
  public Long storeId,buildingId,cabinetId,employeeId;public String scopeKind,area,aisle,bay,requestKey;public Integer cellRow,cellColumn;public LocalDateTime start,end;public Boolean blind;
 }
 private InventoryOrder required(Store store,Long orderId){InventoryOrder order=InventoryOrder.find("id=?1 and store=?2",orderId,store).firstResult();if(order==null)throw new NotFoundException();return org.hibernate.Hibernate.unproxy(order,InventoryOrder.class);}
 public Object list(Long storeId,String state,long before,int limit){Store store=field.store(storeId,false);if(limit<1||limit>100||before<0)throw new BadRequestException("Pagination invalide");var args=new ArrayList<Object>(List.of(store));String where="o.store=?1";if(state!=null&&!state.isBlank()){try{args.add(BaseHandlingOrder.HandlingOrderStatus.valueOf(state));}catch(Exception e){throw new BadRequestException("État inconnu");}where+=" and o.status=?2";}if(before>0){args.add(before);where+=" and o.id<?"+args.size();}var rows=InventoryOrder.<InventoryOrder>find("select o from InventoryOrder o join fetch o.building left join fetch o.assignee where "+where+" order by o.id desc",args.toArray()).range(0,limit).list();var page=rows.stream().limit(limit).toList();var counters=counters(page);return Map.of("items",page.stream().map(o->summary(o,counters.get(id(o)))).toList(),"hasMore",rows.size()>limit,"nextBefore",page.isEmpty()?before:page.getLast().id);}
 private Map<Long,Map<String,Object>> counters(List<InventoryOrder> orders){var result=new HashMap<Long,Map<String,Object>>();if(orders.isEmpty())return result;for(var row:InventoryOrder.getEntityManager().createQuery("select e.handlingOrder.id,e.employee.id,e.employee.firstName,e.employee.lastName from InventoryExecution e where e.handlingOrder.id in ?1 and e.status<>?2 order by e.id desc",Object[].class).setParameter(1,orders.stream().map(com.intermarche.backoffice.domain.fieldops.FieldEntityIds::id).toList()).setParameter(2,com.intermarche.backoffice.domain.handling.HandlingExecution.ExecutionStatus.CANCELLED).getResultList()){String name=java.util.stream.Stream.of(row[2],row[3]).filter(Objects::nonNull).map(Object::toString).collect(java.util.stream.Collectors.joining(" "));result.putIfAbsent((Long)row[0],Map.of("id",row[1],"name",name));}return result;}
 private Map<String,Object> summary(InventoryOrder o){return summary(o,counters(List.of(o)).get(id(o)));}
 private Map<String,Object> summary(InventoryOrder o,Map<String,Object> counter){var v=new LinkedHashMap<String,Object>();v.put("id",o.id);v.put("code",o.code);v.put("status",o.status);v.put("buildingId",id(o.building));v.put("buildingCode",o.building.buildingCode);v.put("scopeKind",o.scopeKind);v.put("scopeLabel",o.scopeLabel);v.put("referenceAt",o.referenceAt);v.put("start",o.requestedStart);v.put("end",o.requestedEnd);v.put("blind",o.blind);v.put("employeeId",counter!=null?counter.get("id"):o.assignee==null?null:id(o.assignee));v.put("employeeName",counter!=null?counter.get("name"):o.assignee==null?null:o.assignee.getFullName());return v;}
 public Object read(Long storeId,Long orderId){Store store=field.store(storeId,false);var order=required(store,orderId);var result=summary(order);result.put("targets",targets(order,field.manager()));return result;}
 public List<Map<String,Object>> targets(InventoryOrder order,boolean supervisor){return InventoryTarget.<InventoryTarget>list("select t from InventoryTarget t left join fetch t.product left join fetch t.segment s left join fetch s.lot left join fetch s.serial where t.handlingOrder=?1 order by t.address,t.id",order).stream().map(t->{Map<String,Object> v=new LinkedHashMap<>();v.put("id",t.id);v.put("address",t.address);v.put("locationId",t.location==null?null:id(t.location));v.put("productId",t.product==null?null:id(t.product));v.put("productName",t.product==null?null:t.product.name);v.put("ean",t.product==null?null:t.product.ean);v.put("bufferId",t.buffer==null?null:id(t.buffer));v.put("cabinetId",t.cabinet==null?null:id(t.cabinet));v.put("cellRow",t.cellRow);v.put("cellColumn",t.cellColumn);if(supervisor||Boolean.FALSE.equals(order.blind)){v.put("expectedQuantity",t.expectedQuantity);v.put("segmentId",t.segment==null?null:id(t.segment));v.put("lotCode",t.segment==null||t.segment.lot==null?null:t.segment.lot.code);v.put("serialCode",t.segment==null||t.segment.serial==null?null:t.segment.serial.code);}return v;}).toList();}
 public Object scopes(Long storeId,Long buildingId){Store store=field.store(storeId,false);Building building=Building.findById(buildingId);if(building==null||!Objects.equals(id(Building.findStoreByBuildingId(id(building))),id(store)))throw new BadRequestException("Bâtiment hors du magasin");var bays=InventoryOrder.getEntityManager().createQuery("select distinct l.area,l.aisle,l.unit from ShelfLocation l where l.id in (select x.id from Building b join b.locations x where b=?1) and type(l) in (StoreShelfLocation,WarehouseShelfLocation) and l.area is not null and l.aisle is not null and l.unit is not null order by l.area,l.aisle,l.unit",Object[].class).setParameter(1,building).getResultList().stream().map(r->Map.of("scopeKind","BAY","area",r[0],"aisle",r[1],"bay",r[2],"label",r[0]+" / "+r[1]+" / "+r[2])).toList();var cells=new ArrayList<Map<String,Object>>();for(var c:BufferCabinet.<BufferCabinet>list("buffer.building=?1 order by buffer.bufferCode,code",building))for(int row=1;row<=c.rows;row++)for(int column=1;column<=c.columns;column++)cells.add(Map.of("scopeKind","CELL","cabinetId",c.id,"cellRow",row,"cellColumn",column,"label",c.buffer.bufferCode+" / "+c.code+" / "+row+"-"+column));return Map.of("bays",bays,"cells",cells);}
 public Object create(Input r){if(r==null||!Set.of("BAY","CELL").contains(r.scopeKind==null?"":r.scopeKind))throw new BadRequestException("Choisissez une baie ou une cellule");Store store=field.store(r.storeId,true);field.requireManager();String fingerprint=field.hash(Arrays.asList("INVENTORY_CREATE",r));var previous=receipts.previous(store,r.requestKey,fingerprint);if(previous!=null)return receipts.value(previous);
  Building building=Building.findById(r.buildingId);if(building==null||!Objects.equals(id(Building.findStoreByBuildingId(id(building))),id(store)))throw new BadRequestException("Bâtiment hors du magasin");
  if(r.start==null||r.end==null||!r.end.isAfter(r.start)||r.end.isAfter(r.start.plusDays(1)))throw new BadRequestException("Créneau d’une journée maximum requis");
  Employee employee=null;if(r.employeeId!=null){employee=Employee.find("id=?1 and store=?2 and active=true",r.employeeId,store).firstResult();if(employee==null||assignments.candidates(store,r.start,r.end,null,null,"HANDLING","PICKER").stream().noneMatch(c->c.employeeId().equals(r.employeeId)))throw new BadRequestException("Employé indisponible pour ce créneau");}
  var locations=new ArrayList<BaseLocation>();BufferCabinet cabinet=null;String label;
  if("BAY".equals(r.scopeKind)){FieldOperationsService.text(r.area,50);FieldOperationsService.text(r.aisle,10);FieldOperationsService.text(r.bay,10);locations.addAll(BaseLocation.<BaseLocation>list("select l from ShelfLocation l where l.id in (select x.id from Building b join b.locations x where b=?1) and l.area=?2 and l.aisle=?3 and l.unit=?4 and type(l) in (StoreShelfLocation,WarehouseShelfLocation)",building,r.area,r.aisle,r.bay));if(locations.isEmpty())throw new BadRequestException("Baie absente de ce bâtiment");label=r.area+" / "+r.aisle+" / "+r.bay;
  }else{cabinet=BufferCabinet.findById(r.cabinetId);if(cabinet==null||!Objects.equals(id(cabinet.buffer.building),id(building))||r.cellRow==null||r.cellColumn==null||r.cellRow<1||r.cellRow>cabinet.rows||r.cellColumn<1||r.cellColumn>cabinet.columns)throw new BadRequestException("Cellule absente de ce bâtiment");label=cabinet.buffer.bufferCode+" / "+cabinet.code+" / "+r.cellRow+"-"+r.cellColumn;locations.addAll(BaseLocation.<BaseLocation>list("select p from PickingToteLocation p where p.protectedTote.cabinet=?1 and p.protectedTote.cellRow=?2 and p.protectedTote.cellColumn=?3",cabinet,r.cellRow,r.cellColumn));locations.addAll(BaseLocation.<BaseLocation>list("select p from BufferToteStockLocation p where p.loadedTote.cabinet=?1 and p.loadedTote.cellRow=?2 and p.loadedTote.cellColumn=?3",cabinet,r.cellRow,r.cellColumn));}
  InventoryOrder order=new InventoryOrder();order.store=store;order.building=building;order.referenceAt=DateTimeProvider.now();order.scopeKind=r.scopeKind;order.scopeLabel=label;order.area=r.area;order.aisle=r.aisle;order.bay=r.bay;order.blind=r.blind==null||r.blind;order.requestedStart=r.start;order.requestedEnd=r.end;order.assignee=employee;order.status=BaseHandlingOrder.HandlingOrderStatus.SCHEDULED;long sequence=((Number)InventoryOrder.getEntityManager().createNativeQuery("select next value for inventory_order_codes_SEQ").getSingleResult()).longValue();String suffix=Long.toString(sequence,36).toUpperCase(Locale.ROOT);if(suffix.length()>6)throw new IllegalStateException("Compteur inventaire épuisé");order.code=order.referenceAt.format(java.time.format.DateTimeFormatter.ofPattern("ddMM"))+"-INV-"+"0".repeat(6-suffix.length())+suffix;order.persistAndFlush();
  var locationIds=locations.stream().map(com.intermarche.backoffice.domain.fieldops.FieldEntityIds::id).toList();var addressed=new HashSet<Long>();
  if(!locationIds.isEmpty())for(var row:StockSegment.getEntityManager().createQuery("select s,coalesce(sum(m.quantity),0) from StockSegment s left join StockMovement m on m.segment=s and m.effectiveAt<=?3 where s.account.store=?1 and s.location.id in ?2 group by s order by s.id",Object[].class).setParameter(1,store).setParameter(2,locationIds).setParameter(3,order.referenceAt).getResultList()){StockSegment segment=(StockSegment)row[0];var target=new InventoryTarget();target.handlingOrder=order;target.location=segment.location;target.product=segment.account.product;target.segment=segment;target.expectedQuantity=(BigDecimal)row[1];target.address=segment.location.locationCode;cell(target,cabinet,r);target.persist();addressed.add(id(segment.location));}
  for(var location:locations)if(!addressed.contains(id(location))){var target=new InventoryTarget();target.handlingOrder=order;target.location=location;target.product=location.product;target.expectedQuantity=BigDecimal.ZERO;target.address=location.locationCode;cell(target,cabinet,r);target.persist();}
  if(locations.isEmpty()){var target=new InventoryTarget();target.handlingOrder=order;target.address=label;target.expectedQuantity=BigDecimal.ZERO;cell(target,cabinet,r);target.persist();}
  return receipts.record(store,r.requestKey,fingerprint,"INVENTORY_CREATE",read(id(store),order.id));
 }
 private static void cell(InventoryTarget target,BufferCabinet cabinet,Input input){if(cabinet!=null){target.buffer=cabinet.buffer;target.cabinet=cabinet;target.cellRow=input.cellRow;target.cellColumn=input.cellColumn;}}
}
